"""RoboPaint: calibrated single-sweep oil painting from target RGB and camera observations."""
import sys,os,json,time,math
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot();o=self.r.get_obs(cameras=[]);self.pos=np.array(o.meta['proprio']['now'][7:10]);self.rows=[];self.last=o;self.col=None
 def go(self,p,speed=.15,hold=0):
  p=np.array(p,float);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/speed/.05)))
  for a in np.linspace(0,1,n+1)[1:]:self.rows.append([*(self.pos*(1-a)+p*a),0,1,0,0])
  self.rows.extend([[*p,0,1,0,0]]*int(round(hold/.05)));self.pos=p
 def flush(self,note=''):
  while self.rows:
   a=self.rows[:190];self.rows=self.rows[190:];before=self.r.status()
   with open(OUT+'/actions.jsonl','a') as f:f.write(json.dumps({'before':before,'note':note,'actions':a})+'\n')
   try:self.last=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none',note=note)
   except Exception:
    s=self.r.wait_ready();
    if s['control_steps']==before['control_steps']:self.last=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none',note=note)
    else: self.last=self.r.get_obs(cameras=[])
   if self.last.done:raise RuntimeError(self.last.meta)
   failures=sum(p.get('ik_failures',0) for p in self.last.meta.get('plan',[]))
   if failures:print('IK failures',failures,flush=True)
 def dip(self,k):
  x=-.156+.022*(k%6);y=.137+.022*(k//6)
  if k>=12:x=-.134+.022*(k-12);y=.181
  self.go([*self.pos[:2],.065]);self.go([x,y,.065]);self.go([x,y,.024],hold=.25);self.go([x,y,.065],hold=.15);self.col=k
 def stroke_world(self,points,depth,speed=.035):
  z=.0202-depth
  self.go([*self.pos[:2],.045]);self.go([*points[0],.045]);self.go([*points[0],z],speed=.05,hold=.25)
  for p in points[1:]:self.go([*p,z],speed=speed)
  self.go([*points[-1],z],hold=.15);self.go([*points[-1],.045],speed=.06,hold=.15)
 def stroke(self,points,depth,speed=.035):
  self.stroke_world([[.0135925-v*.227185/1024,.1135925-u*.227185/1024] for u,v in points],depth,speed)
 def park(self):
  self.go([*self.pos[:2],.08]);self.go([-.1,.22,.10],hold=.3);self.flush('park')
 def photo(self,name,cams=['canvas_cam']):
  self.park();o=self.r.get_obs(cameras=cams)
  for k,v in o.last.items():Image.fromarray(v).save(f'{OUT}/{name}_{k}.png')
  return o
if __name__=='__main__':
